import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = [int(x) for x in data[1:1 + n]]
    INF = float('inf')
    d = [[INF] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    pos = 1 + n
    for _ in range(n - 1):
        u = int(data[pos]) - 1; v = int(data[pos + 1]) - 1; w = int(data[pos + 2])
        pos += 3
        d[u][v] = w
        d[v][u] = w
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if d[i][k] + d[k][j] < d[i][j]:
                    d[i][j] = d[i][k] + d[k][j]
    for v in range(n):
        print(sum(a[u] * d[v][u] for u in range(n)))

main()
